class Solution {
    public String minWindow(String s, String t) {
        int[]cntS = new int[130];
        int[]cntT = new int[130];
        for(int i = 0;i<t.length();i++){
            cntT[t.charAt(i)]++;
        }
        int left = 0;
        int right = 0;
        int resleft = 0;
        int reslen = Integer.MAX_VALUE;
        for(;right<s.length();right++){
            cntS[s.charAt(right)]++;
            while(isCovered(cntS,cntT)){
                if(right-left+1<reslen){
                    resleft = left;
                    reslen = right-left+1;
                }
                cntS[s.charAt(left)]--;
                left++;
            }
        }
        return reslen==Integer.MAX_VALUE?"":s.substring(resleft,resleft+reslen);
    }
    public boolean isCovered(int[]cntS,int[]cntT){
        for(int i = 'a';i<='z';i++){
            if(cntT[i]>cntS[i]){
                return false;
            }
        }
        for(int i = 'A';i<='Z';i++){
            if(cntT[i]>cntS[i]){
                return false;
            }
        }
        return true;
    }
}
